package com.mealmate.payment; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.context.annotation.Bean; import io.swagger.v3.oas.models.OpenAPI; import io.swagger.v3.oas.models.servers.Server; import java.util.List; @SpringBootApplication public class PaymentApplication { public static void main(String[] a){SpringApplication.run(PaymentApplication.class,a);} @Bean OpenAPI mealMateOpenAPI(){return new OpenAPI().servers(List.of(new Server().url("http://localhost:9000"))).components(new io.swagger.v3.oas.models.Components().addSecuritySchemes("bearerAuth",new io.swagger.v3.oas.models.security.SecurityScheme().type(io.swagger.v3.oas.models.security.SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT"))).addSecurityItem(new io.swagger.v3.oas.models.security.SecurityRequirement().addList("bearerAuth"));} }
